-- Входящие SMS («1»/«2», «СТОП») SMS-шлюз не принимает: шаблоны по умолчанию переводятся
-- на подписанную ссылку {{reply.link}} (изменённые клиникой тексты не трогаем)
UPDATE "NotificationTemplate" SET "body" = 'Уважаемый(ая) {{patient.firstName}}! Напоминаем о приёме: {{doctor.name}}, {{start.date}} в {{start.time}}, {{clinic.name}}. Подтвердить или отменить: {{reply.link}}' WHERE "body" = 'Уважаемый(ая) {{patient.firstName}}! Напоминаем о приёме: {{doctor.name}}, {{start.date}} в {{start.time}}, клиника {{clinic.name}}. Ответьте: 1 — подтверждаю, 2 — отменяю.';
UPDATE "NotificationTemplate" SET "body" = 'До приёма у {{doctor.name}} осталось меньше суток — {{start.date}} в {{start.time}}. Если планы изменились, отмените запись: {{reply.link}} — мы предложим время другому пациенту. {{clinic.name}}.' WHERE "body" = 'До приёма у {{doctor.name}} осталось меньше суток — {{start.date}} в {{start.time}}. Если планы изменились, ответьте «2», и мы предложим время другому пациенту. Клиника {{clinic.name}}.';
UPDATE "NotificationTemplate" SET "body" = 'Через 3 часа приём: {{doctor.name}} в {{start.time}}. Ждём вас! {{clinic.name}}. Подтвердить или отменить: {{reply.link}}' WHERE "body" = 'Через 3 часа приём: {{doctor.name}} в {{start.time}}. Ждём вас в {{clinic.name}}! Ответьте: 1 — подтверждаю, 2 — отменяю.';
UPDATE "NotificationTemplate" SET "body" = '{{patient.firstName}}, освободилось время у врача {{doctor.name}}: {{start.date}} в {{start.time}}. Записаться или отказаться: {{reply.link}} Предложение действует {{offer.ttl}} минут.' WHERE "body" = '{{patient.firstName}}, освободилось время у врача {{doctor.name}}: {{start.date}} в {{start.time}}. Ответьте: 1 — записаться, 2 — не подходит. Предложение удерживается {{offer.ttl}} минут.';
UPDATE "NotificationTemplate" SET "body" = '{{patient.firstName}}, подтвердите, пожалуйста, приём у {{doctor.name}} — {{start.date}} в {{start.time}}: {{reply.link}} Если планы изменились, отмените запись там же — предложим время другому пациенту. {{clinic.name}}.' WHERE "body" = '{{patient.firstName}}, подтвердите, пожалуйста, приём у {{doctor.name}} — {{start.date}} в {{start.time}}. Если планы изменились, ответьте «2» — предложим слот другому пациенту. {{clinic.name}}.';
